def maxWater(arr):
    n = len(arr)
    if n <= 2: return 0
    left, right = 0, n - 1
    left_max, right_max = 0, 0
    res = 0
    while left < right:
        if arr[left] < arr[right]:
            if arr[left] >= left_max:
                left_max = arr[left]
            else:
                res += left_max - arr[left]
            left += 1
        else:
            if arr[right] >= right_max:
                right_max = arr[right]
            else:
                res += right_max - arr[right]
            right -= 1
    return res

if __name__ == "__main__":
    n = int(input())
    arr = list(map(int, input().split()))
    print(maxWater(arr))

